 32	// ---------------------------------------------------------------------------
 33	
 34	function parseIgnoreFile(filePath: string): string[] {
 35	  const content = readFileSync(filePath, "utf8");
 36	  const patterns: string[] = [];
 37	  for (const line of content.split("\n")) {
 38	    const trimmed = line.trim();
 39	    if (!trimmed || trimmed.startsWith("#")) continue;
 40	    patterns.push(trimmed);
 41	  }
 42	  return patterns;
 43	}
 44	
 45	function loadIgnorePatterns(root: string): string[] {
 46	  const patterns: string[] = [];
 47	  // Always exclude .git directory
 48	  patterns.push(".git/");
 49	  for (const name of [".xxignore", ".gitignore"]) {
 50	    const p = join(root, name);
 51	    if (existsSync(p)) {
 52	      patterns.push(...parseIgnoreFile(p));
 53	    }
 54	  }
 55	  return patterns;
 56	}
