 58	function isIgnored(relPath: string, patterns: string[]): boolean {
 59	  for (const pattern of patterns) {
 60	    const anchored = pattern.startsWith("/");
 61	    const p = anchored ? pattern.slice(1) : pattern;
 62	    const dirOnly = p.endsWith("/");
 63	    const base = dirOnly ? p.slice(0, -1) : p;
 64	
 65	    if (matchGlobLike(relPath, base, anchored)) return true;
 66	    if (dirOnly && relPath.startsWith(base + "/")) return true;
 67	  }
 68	  return false;
 69	}
 70	
 71	function matchGlobLike(path: string, pattern: string, anchored: boolean): boolean {
 72	  if (pattern === "**") return true;
 73	
 74	  if (pattern.startsWith("**/")) {
 75	    const rest = pattern.slice(3);
 76	    let p = path;
 77	    while (true) {
 78	      if (simpleMatch(p, rest)) return true;
 79	      const idx = p.indexOf("/");
 80	      if (idx < 0) break;
 81	      p = p.slice(idx + 1);
 82	    }
 83	    return false;
 84	  }
 85	
 86	  if (pattern.endsWith("/**")) {
 87	    const prefix = pattern.slice(0, -3);
 88	    return path === prefix || path.startsWith(prefix + "/");
 89	  }
 90	
 91	  if (anchored) {
 92	    return simpleMatch(path, pattern);
 93	  }
 94	
 95	  if (simpleMatch(path, pattern)) return true;
 96	  const basename = path.split("/").pop() ?? path;
 97	  if (simpleMatch(basename, pattern)) return true;
 98	
 99	  return false;
100	}
101	
102	function simpleMatch(path: string, pattern: string): boolean {
103	  if (!pattern.includes("*") && !pattern.includes("?")) {
104	    return path === pattern;
105	  }
106	
107	  // Escape regex special characters except * and ?
108	  const special = /[.+^${}()|[\]\\-]/g;
109	  const escaped = pattern.replace(special, "\\$&");
110	  // Then turn * and ? into regex tokens
111	  const regexStr = "^" + escaped.replace(/\*/g, "[^/]*").replace(/\?/g, "[^/]") + "$";
112	  try {
113	    return new RegExp(regexStr).test(path);
114	  } catch {
115	    return false;
116	  }
117	}
