119	// ---------------------------------------------------------------------------
120	// File discovery (via git ls-files)
121	// ---------------------------------------------------------------------------
122	
123	/**
124	 * Get all tracked files in a git repo, respecting ignore patterns.
125	 * Uses `git ls-files` for speed and correctness.
126	 */
127	async function discoverFiles(
128	  root: string,
129	  ignorePatterns: string[]
130	): Promise<string[]> {
131	  let output: string;
132	  try {
133	    output = execSync(
134	      "git ls-files --cached --others --exclude-standard",
135	      { cwd: root, encoding: "utf8", timeout: 10000, stdio: ["ignore", "pipe", "ignore"] }
136	    );
137	  } catch {
138	    // Not a git repo or git unavailable — fall back to filesystem walk
139	    return discoverFilesByWalk(root, ignorePatterns);
140	  }
141	
142	  const allFiles = output.trim().split("\n").filter(Boolean);
143	  // Filter through our ignore patterns (git's --exclude-standard already
144	  // handles .gitignore, but we also need .xxignore)
145	  return allFiles.filter((f) => !isIgnored(f, ignorePatterns));
146	}
147	
148	/**
149	 * Fallback: walk the filesystem to discover files.
150	 * Used when git is not available.
151	 */
152	async function discoverFilesByWalk(
153	  root: string,
154	  ignorePatterns: string[]
155	): Promise<string[]> {
156	  const results: string[] = [];
157	
158	  async function walk(dir: string): Promise<void> {
159	    let entries;
160	    try {
161	      entries = await readdir(dir, { withFileTypes: true });
162	    } catch {
163	      return;
164	    }
165	    for (const entry of entries) {
166	      const fullPath = join(dir, entry.name);
167	      const relPath = relative(root, fullPath);
168	
169	      if (isIgnored(relPath, ignorePatterns)) continue;
170	
171	      if (entry.isDirectory()) {
172	        await walk(fullPath);
173	      } else if (entry.isFile()) {
174	        results.push(relPath);
175	      }
176	    }
177	  }
178	
179	  await walk(root);
180	  return results;
181	}
