194	function getGitTimestamp(filePath: string, cwd: string): number {
195	  try {
196	    const rel = relative(cwd, filePath);
197	    const out = execSync(
198	      `git log -1 --format=%ct -- "${rel}" 2>/dev/null || echo "0"`,
199	      { cwd, encoding: "utf8", timeout: 5000 }
200	    );
201	    const ts = parseInt(out.trim(), 10);
202	    return Number.isFinite(ts) ? ts * 1000 : 0;
203	  } catch {
204	    return 0;
205	  }
206	}
207	
208	function countReferences(filePath: string): number {
209	  try {
210	    const content = readFileSync(filePath, "utf8");
211	    const importPatterns = [
212	      /(?:import|export)\s+/g,
213	      /require\s*\(/g,
214	      /from\s+['"]/g,
215	    ];
216	    let count = 0;
217	    for (const re of importPatterns) {
218	      const matches = content.match(re);
219	      if (matches) count += matches.length;
220	    }
221	    return count;
222	  } catch {
223	    return 0;
224	  }
225	}
226	
227	function computeProximityScore(relPath: string, focusPaths: string[]): number {
228	  if (focusPaths.length === 0) return 0;
229	
230	  let maxScore = 0;
231	  for (const fp of focusPaths) {
232	    const normalizedFp = fp.replace(/\/$/, "");
233	    if (relPath === normalizedFp || relPath.startsWith(normalizedFp + "/")) {
234	      const depth = relPath.slice(normalizedFp.length).split("/").filter(Boolean).length;
235	      maxScore = Math.max(maxScore, 1 / (1 + depth));
236	    } else {
237	      const commonLen = commonPrefixLength(relPath, normalizedFp);
238	      if (commonLen > 0) {
239	        maxScore = Math.max(maxScore, commonLen / Math.max(relPath.length, normalizedFp.length));
240	      }
241	    }
242	  }
243	  return maxScore;
244	}
245	
246	function commonPrefixLength(a: string, b: string): number {
247	  let i = 0;
248	  while (i < a.length && i < b.length && a[i] === b[i]) i++;
249	  return i;
250	}
