260	// ---------------------------------------------------------------------------
261	// Main entry point
262	// ---------------------------------------------------------------------------
263	
264	export async function buildRepoMap(options: BuildRepoMapOptions): Promise<RepoMapResult> {
265	  const { root, tokenBudget = 8000, focusPaths = [], includeSymbols = false } = options;
266	
267	  const resolvedRoot = resolve(root);
268	  if (!existsSync(resolvedRoot)) {
269	    throw new Error(`Repo root not found: ${resolvedRoot}`);
270	  }
271	
272	  const ignorePatterns = loadIgnorePatterns(resolvedRoot);
273	  const allFiles = await discoverFiles(resolvedRoot, ignorePatterns);
274	  if (allFiles.length === 0) {
275	    return { files: [], tokensEstimated: 0, method: "heuristic" };
276	  }
277	
278	  const signals: FileSignals[] = [];
279	  for (const relPath of allFiles) {
280	    const fullPath = join(resolvedRoot, relPath);
281	    const gitTimestamp = getGitTimestamp(fullPath, resolvedRoot);
282	    const proximityScore = computeProximityScore(relPath, focusPaths);
283	    const refCount = countReferences(fullPath);
284	    signals.push({ path: relPath, gitTimestamp, proximityScore, refCount });
285	  }
286	
287	  const maxTs = Math.max(...signals.map((s) => s.gitTimestamp), 1);
288	  const maxRef = Math.max(...signals.map((s) => s.refCount), 1);
289	
290	  for (const s of signals) {
291	    const recency = s.gitTimestamp / maxTs;
292	    const refNorm = s.refCount / maxRef;
293	    const focus = s.proximityScore;
294	    s.proximityScore = recency * 0.3 + refNorm * 0.3 + focus * 0.4;
295	  }
296	
297	  signals.sort((a, b) => b.proximityScore - a.proximityScore);
298	
299	  const selected: RepoMapFile[] = [];
300	  let runningTokens = 0;
301	
302	  for (const s of signals) {
303	    const fullPath = join(resolvedRoot, s.path);
304	    let fileContent = "";
305	    let fileTokens = 0;
306	    try {
307	      fileContent = readFileSync(fullPath, "utf8");
308	      fileTokens = estimateTokens(fileContent);
309	    } catch {
310	      fileTokens = 0;
311	    }
312	
313	    if (runningTokens + fileTokens > tokenBudget && selected.length > 0) {
314	      if (runningTokens + fileTokens > tokenBudget * 2) break;
315	    }
316	
317	    const ranges = fileTokens > 0
318	      ? [{ startLine: 1, endLine: fileContent.split("\n").length }]
319	      : [];
320	
321	    let symbols: string[] | undefined;
322	    if (includeSymbols) {
323	      symbols = extractSymbols(fileContent);
324	    }
325	
326	    selected.push({
327	      path: s.path,
328	      score: s.proximityScore,
329	      ranges,
330	      symbols,
331	    });
332	
333	    runningTokens += fileTokens;
334	  }
335	
336	  return {
337	    files: selected,
338	    tokensEstimated: runningTokens,
339	    method: "heuristic",
340	  };
341	}
342	
343	function extractSymbols(content: string): string[] {
344	  const symbols: string[] = [];
345	  const patterns = [
346	    /(?:export\s+)?(?:async\s+)?function\s+(\w+)/g,
347	    /(?:export\s+)?class\s+(\w+)/g,
348	    /(?:export\s+)?(?:const|let|var)\s+(\w+)\s*[:=]\s*(?:async\s+)?\(/g,
349	    /(?:export\s+)?interface\s+(\w+)/g,
350	    /(?:export\s+)?type\s+(\w+)\s*=/g,
351	    /(?:export\s+)?enum\s+(\w+)/g,
352	    /def\s+(\w+)\s*\(/g,
353	    /class\s+(\w+)/g,
354	  ];
355	  for (const re of patterns) {
356	    let m: RegExpExecArray | null;
357	    while ((m = re.exec(content)) !== null) {
358	      symbols.push(m[1]);
359	    }
360	  }
361	  return [...new Set(symbols)];
362	}

